import { Timer as TimerPrimitive, useTimer, useTimerContext } from '@ark-ui/solid/timer';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { Index, splitProps } from 'solid-js';
import styles from './Timer.module.css';

function Timer(props: ComponentProps<typeof TimerPrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="timer-root"
    />
  );
}

function TimerRootProvider(props: ComponentProps<typeof TimerPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="timer-root-provider"
    />
  );
}

function TimerArea(props: ComponentProps<typeof TimerPrimitive.Area>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.Area
      class={clsx(styles.area, local.class)}
      {...others}
      data-slot="timer-area"
    />
  );
}

function TimerItem(props: ComponentProps<typeof TimerPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="timer-item"
    />
  );
}

function TimerSeparator(props: ComponentProps<typeof TimerPrimitive.Separator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.Separator
      class={clsx(styles.separator, local.class)}
      {...others}
      data-slot="timer-separator"
    />
  );
}

function TimerControl(props: ComponentProps<typeof TimerPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="timer-control"
    />
  );
}

function TimerActionTrigger(props: ComponentProps<typeof TimerPrimitive.ActionTrigger>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TimerPrimitive.ActionTrigger
      class={clsx(styles.actionTrigger, local.class)}
      {...others}
      data-slot="timer-action-trigger"
    />
  );
}

type TimerItemType = ComponentProps<typeof TimerPrimitive.Item>['type'];
type TimerSegmentsProps = Omit<
  ComponentProps<typeof TimerPrimitive.Area>,
  'asChild' | 'children'
> & {
  separator?: JSX.Element;
  types?: TimerItemType[];
};
type TimerTickDetails = Parameters<
  NonNullable<ComponentProps<typeof TimerPrimitive.Root>['onTick']>
>[0];

const defaultTimerSegmentTypes: TimerItemType[] = ['hours', 'minutes', 'seconds'];

function TimerSegments(props: TimerSegmentsProps) {
  const [local, others] = splitProps(props, ['separator', 'types']);
  const types = () => local.types ?? defaultTimerSegmentTypes;

  return (
    <TimerArea {...others}>
      <Index each={types()}>
        {(type, index) => (
          <>
            <TimerItem type={type()} />
            {index < types().length - 1 && (
              <TimerSeparator>{local.separator ?? ':'}</TimerSeparator>
            )}
          </>
        )}
      </Index>
    </TimerArea>
  );
}

const TimerContext = TimerPrimitive.Context;

export {
  Timer,
  TimerActionTrigger,
  TimerArea,
  TimerContext,
  TimerControl,
  TimerItem,
  TimerRootProvider,
  TimerSegments,
  TimerSeparator,
  useTimer,
  useTimerContext,
};

export type {
  TimerActionTriggerProps,
  TimerAreaProps,
  TimerContextProps,
  TimerControlProps,
  TimerItemProps,
  TimerRootProps,
  TimerRootProviderProps,
  TimerSeparatorProps,
  UseTimerContext,
  UseTimerProps,
  UseTimerReturn,
} from '@ark-ui/solid/timer';
export type { TimerSegmentsProps, TimerTickDetails };

@layer moduix.components {
  .root {
    display: inline-grid;
    place-items: center;
    gap: var(--moduix-spacing-3);
    width: max-content;
    max-inline-size: 100%;
    color: var(--moduix-color-foreground);
  }

  .area {
    display: inline-flex;
    min-inline-size: 0;
    max-inline-size: 100%;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: center;
    gap: var(--moduix-spacing-1);
    font-size: var(--moduix-text-2xl);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-2xl);
    font-variant-numeric: tabular-nums;
  }

  .item {
    min-width: 2ch;
    text-align: center;
  }

  .separator {
    color: var(--moduix-color-muted-foreground);
  }

  .control {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--moduix-spacing-2);
  }

  .actionTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-md);
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1-5) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    appearance: none;
    font: inherit;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    white-space: nowrap;
    cursor: pointer;
    transition: background-color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:disabled {
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
      pointer-events: none;
    }

    &[hidden] {
      display: none;
    }

    & :where(svg) {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }
}
